// BaselineNestedArrowReader is a strongly-typed Apache Arrow reader for BaselineNested.
type BaselineNestedArrowReader struct {
	colFlag  *array.Boolean
	colValue *array.Uint64
}

// NewBaselineNestedArrowReader creates a new Arrow reader for BaselineNested from a RecordBatch.
// It validates column types at construction time; if a column exists with the wrong
// type, an error is returned. Missing columns are silently skipped during LoadRow.
func NewBaselineNestedArrowReader(rec arrow.RecordBatch) (*BaselineNestedArrowReader, error) {
	r := &BaselineNestedArrowReader{}
	schema := rec.Schema()
	if indices := schema.FieldIndices("Flag"); len(indices) > 0 {
		col, ok := rec.Column(indices[0]).(*array.Boolean)
		if !ok {
			return nil, fmt.Errorf("column %q: expected *array.Boolean, got %T", "Flag", rec.Column(indices[0]))
		}
		r.colFlag = col
	}
	if indices := schema.FieldIndices("Value"); len(indices) > 0 {
		col, ok := rec.Column(indices[0]).(*array.Uint64)
		if !ok {
			return nil, fmt.Errorf("column %q: expected *array.Uint64, got %T", "Value", rec.Column(indices[0]))
		}
		r.colValue = col
	}
	return r, nil
}

func newBaselineNestedArrowReaderFromStruct(col *array.Struct) (*BaselineNestedArrowReader, error) {
	r := &BaselineNestedArrowReader{}
	dt := col.DataType().(*arrow.StructType)
	_ = dt
	_ = col
	if idx, ok := dt.FieldIdx("Flag"); ok {
		child, ok := col.Field(idx).(*array.Boolean)
		if !ok {
			return nil, fmt.Errorf("struct field %q: expected *array.Boolean, got %T", "Flag", col.Field(idx))
		}
		r.colFlag = child
	}
	if idx, ok := dt.FieldIdx("Value"); ok {
		child, ok := col.Field(idx).(*array.Uint64)
		if !ok {
			return nil, fmt.Errorf("struct field %q: expected *array.Uint64, got %T", "Value", col.Field(idx))
		}
		r.colValue = child
	}
	return r, nil
}

// LoadRow loads the i-th row from the Arrow record into the output struct.
// A field whose column is missing from the record is set to its zero value.
func (r *BaselineNestedArrowReader) LoadRow(i int, out *BaselineNested) {
	if r.colFlag == nil {
		out.Flag = false
	} else {
		if r.colFlag.IsNull(i) {
			out.Flag = false
		} else {
			out.Flag = bool(r.colFlag.Value(i))
		}
	}
	if r.colValue == nil {
		out.Value = 0
	} else {
		if r.colValue.IsNull(i) {
			out.Value = 0
		} else {
			out.Value = uint64(r.colValue.Value(i))
		}
	}
}
